// stopWithSignal terminates the process using the provided signal.
//
// waitTimeout - the time that was provided to the process
// to terminate correctly before the "SIGKILL" signal is used.
func (pc *processController) stopWithSignal(waitTimeout time.Duration, sig os.Signal) error {
	if !pc.IsAlive() {
		return nil
	}

	// Сreate a channel to receive an indication of the termination
	// of the Instance.
	waitDone := make(chan error, 1)
	go func() {
		waitDone <- pc.Wait()
	}()

	// Trying to terminate the process by using the provided signal.
	// In case of failure a "SIGKILL" signal will be used.
	if err := pc.SendSignal(sig); err != nil {
		return fmt.Errorf("failed to send %v to instance: %s", sig, err)
	}

	// Terminate the process at any cost.
	select {
	case <-time.After(waitTimeout):
		// Send "SIGKILL" signal
		if err := pc.cmd.Process.Kill(); err != nil {
			return fmt.Errorf("failed to send SIGKILL to instance: %s", err)
		} else {
			// Wait for the process to terminate.
			<-waitDone
			return nil
		}
	case err := <-waitDone:
		return err
	}
}

// Stop terminates the process.
//
// timeout - the time that was provided to the process
// to terminate correctly before the "SIGKILL" signal is used.
func (pc *processController) Stop(waitTimeout time.Duration) error {
	return pc.stopWithSignal(waitTimeout, os.Interrupt)
}

// Quit terminates the process.
func (pc *processController) Quit(waitTimeout time.Duration) error {
	return pc.stopWithSignal(waitTimeout, syscall.SIGQUIT)
}

